def max_len_sub(arr, k):
    """
    Find the maximum length of a subsequence where the difference between adjacent elements is at most k.
    """
    if not arr:
        return 0

    n = len(arr)
    # dp[i] represents the maximum length of a valid subsequence ending at index i
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if abs(arr[i] - arr[j]) <= k:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
